// frontend/src/components/ReportsPage.tsx
import React, { useEffect, useState } from "react";
import api, { setTenantId } from "../services/api";

export default function ReportsPage() {
  // Simulate tenant selection
  const tenantId = process.env.REACT_APP_TENANT_ID || "11111111-1111-1111-1111-111111111111";
  setTenantId(tenantId);

  const [start, setStart] = useState<string>(() => { const d = new Date(); d.setDate(d.getDate()-30); return d.toISOString().slice(0,16); });
  const [end, setEnd] = useState<string>(() => new Date().toISOString().slice(0,16));
  const [reportJson, setReportJson] = useState<any>(null);

  async function loadReport() {
    const clientLocalTime = new Date().toISOString();
    const resp = await api.get("/api/reports/data", {
      params: {
        start: new Date(start).toISOString(),
        end: new Date(end).toISOString(),
        clientLocalTime
      }
    });
    setReportJson(resp.data);
  }

  useEffect(() => { loadReport(); }, []);

  return (
    <div>
      <h2>Reports</h2>
      <div>
        From <input type="datetime-local" value={start} onChange={e=>setStart(e.target.value)} />
        To <input type="datetime-local" value={end} onChange={e=>setEnd(e.target.value)} />
        <button onClick={loadReport}>Refresh</button>
      </div>

      {reportJson && (
        <div>
          <div>Report Generated On (your local time): {new Date(reportJson.reportGeneratedOn).toLocaleString()}</div>
          <table>
            <thead><tr><th>Name</th><th>Start</th><th>End</th><th>Venue</th><th>#Attendees</th></tr></thead>
            <tbody>
              {reportJson.data.map((r:any) => (
                <tr key={r.id}>
                  <td>{r.name}</td>
                  <td>{new Date(r.startTimeUtc).toLocaleString()}</td>
                  <td>{new Date(r.endTimeUtc).toLocaleString()}</td>
                  <td>{r.venue}</td>
                  <td>{r.attendeeCount}</td>
                </tr>
              ))}
            </tbody>
          </table>

          {/* If you prefer Bold Reports viewer, you'd initialize it here and pass reportJson.data as the dataset to the viewer. */}
        </div>
      )}
    </div>
  );
}
